Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
SUNRPC: svcauth_gss: avoid NULL deref on zero length
 gss_token in gss_read_proxy_verf

A zero length gss_token results in pages == 0 and in_token->pages[0]
is NULL. The code unconditionally evaluates
page_address(in_token->pages[0]) for the initial memcpy, which can
dereference NULL even when the copy length is 0. Guard the first
memcpy so it only runs when length > 0.

Fixes: 5866efa8cbfb ("SUNRPC: Fix svcauth_gss_proxy_init()")
Cc: stable@vger.kernel.org
Signed-off-by: Joshua Rogers <linux@joshua.hu>
Signed-off-by: Chuck Lever <chuck.lever@oracle.com>

Here is the root cause:
When a zero-length gss_token is received, `pages` is set to 0 and `in_token->pages[0]` is NULL. The code unconditionally calls `page_address(in_token->pages[0])` in the `memcpy` call, leading to a NULL pointer dereference even though the copy length is zero. The missing length check before accessing the page pointer causes the bug.

Here is the patch:

 static int gss_read_proxy_verf(struct svc_rqst *rqstp,
 			       struct rpc_gss_wire_cred *gc,
 			       struct xdr_netobj *in_handle,
 			       struct gssp_in_token *in_token)
 {
 	struct xdr_stream *xdr = &rqstp->rq_arg_stream;
 	unsigned int length, pgto_offs, pgfrom_offs;
 	int pages, i, pgto, pgfrom;
 	size_t to_offs, from_offs;
 	u32 inlen;

 	if (dup_netobj(in_handle, &gc->gc_ctx))
 		return SVC_CLOSE;

 	/*
 	 *  RFC 2203 Section 5.2.2
 	 *
 	 *	struct rpc_gss_init_arg {
 	 *		opaque gss_token<>;
 	 *	};
 	 */
 	if (xdr_stream_decode_u32(xdr, &inlen) < 0)
 		goto out_denied_free;
 	if (inlen > xdr_stream_remaining(xdr))
 		goto out_denied_free;

 	pages = DIV_ROUND_UP(inlen, PAGE_SIZE);
 	in_token->pages = kcalloc(pages + 1, sizeof(struct page *), GFP_KERNEL);
 	if (!in_token->pages)
 		goto out_denied_free;
 	in_token->page_base = 0;
 	in_token->page_len = inlen;
 	for (i = 0; i < pages; i++) {
 		in_token->pages[i] = alloc_page(GFP_KERNEL);
 		if (!in_token->pages[i]) {
 			gss_free_in_token_pages(in_token);
 			goto out_denied_free;
 		}
 	}

 	length = min_t(unsigned int, inlen, (char *)xdr->end - (char *)xdr->p);
-	memcpy(page_address(in_token->pages[0]), xdr->p, length);
+	if (length)
+		memcpy(page_address(in_token->pages[0]), xdr->p, length);
 	inlen -= length;

 	to_offs = length;
 	from_offs = rqstp->rq_arg.page_base;
 	while (inlen) {
 		pgto = to_offs >> PAGE_SHIFT;
 		pgfrom = from_offs >> PAGE_SHIFT;
 		pgto_offs = to_offs & ~PAGE_MASK;
 		pgfrom_offs = from_offs & ~PAGE_MASK;

 		length = min_t(unsigned int, inlen,
 			 min_t(unsigned int, PAGE_SIZE - pgto_offs,
 			       PAGE_SIZE - pgfrom_offs));
 		memcpy(page_address(in_token->pages[pgto]) + pgto_offs,
 		       page_address(rqstp->rq_arg.pages[pgfrom]) + pgfrom_offs,
 		       length);

 		to_offs += length;
 		from_offs += length;
 		inlen -= length;
 	}
 	return 0;

 out_denied_free:
 	kfree(in_handle->data);
 	return SVC_DENIED;
 }



